import yaml
with open('docker-compose.yaml', 'r') as f:
    data = yaml.safe_load(f)

nats = data['services']['nats']

# Base64 of nats-server.conf
b64_conf = ""

nats['entrypoint'] = ['/bin/sh', '-c']
nats['command'] = f'echo "{b64_conf}" | base64 -d > /tmp/nats.conf && nats-server -c /tmp/nats.conf'
# Filter out the bind mount that was failing
nats['volumes'] = [v for v in nats.get('volumes', []) if 'nats-server.conf' not in v]

with open('docker-compose.yaml', 'w') as f:
    yaml.dump(data, f, default_flow_style=False, sort_keys=False)

